// Files generated by `praeko studio init` and `praeko studio new`.
// Versions `init` pins in the new project: Remotion, React and Studio's own (injected at build time; in development they come from package.json).
export const VERSIONS = { remotion: "4.0.539", react: "19.2.3", reactTypes: "19.2.7", typescript: "5.9.3" };
/** New project: dependencies by published version (semver). With `dev` (path to the Studio repository) it uses `file:` (the way contributors work). */
export const projectPackage = ({ name, dev = null, studioVersion = "0.2.0" }: { name: string; dev?: string | null; studioVersion?: string }): string => JSON.stringify({
  name, version: "0.0.1", private: true,
  scripts: { dev: "remotion studio src/index.ts" },
  dependencies: {
    "@praeko/studio-core": dev ? `file:${dev}/packages/core` : `^${studioVersion}`,
    "@praeko/studio-kit": dev ? `file:${dev}/packages/kit` : `^${studioVersion}`,
    "@remotion/cli": VERSIONS.remotion, react: VERSIONS.react, "react-dom": VERSIONS.react, remotion: VERSIONS.remotion,
  },
  devDependencies: { ...(dev ? {} : { "@praeko/studio": `^${studioVersion}` }), "@types/react": VERSIONS.reactTypes, typescript: VERSIONS.typescript },
}, null, 2) + "\n";

export const initialBrand = ({ name, handle }: { name: string; handle: string }): string => JSON.stringify({
  name, handle, avatar: "cover/avatar.png",
  colors: { background: "#14110f", coverBackground: "#0e0c14", accent: "#f4b942", text: "#f3ece0", muted: "#a89c8a", ok: "#7ee787", error: "#ff6b5e", info: "#7fd7ff", extra: "#a98bff", box: "#2a2118", code: "#1b1610" },
  fonts: { title: "'Arial Black', 'Helvetica Neue', system-ui, sans-serif", mono: "Menlo, 'Courier New', monospace" },
  signature: "",
  links: {},
  voice: "draft-silent", pronunciation: {}, captionFixes: {}, bannedNames: [],
  publishing: { provider: "praeko", hashtags: { allowed: [], banned: [] } },
}, null, 2) + "\n";

export const remotionConfigBase = `import { Config } from "@remotion/cli/config";

Config.setRspack(true);
Config.setVideoImageFormat("jpeg");
// macOS: GPU through ANGLE/Metal is ~1.7x faster on Shorts (blur, shadows). Other systems keep Remotion's default.
if (process.platform === "darwin") Config.setChromiumOpenGlRenderer("angle");
Config.setOverwriteOutput(true);
Config.setDefaultPremountInSeconds(2);
`;
/** Only in --dev mode (Studio linked by local path, symlink): forces a single copy of remotion/react, this project's. */
export const remotionConfigDev = remotionConfigBase.replace('import { Config } from "@remotion/cli/config";\n', 'import { Config } from "@remotion/cli/config";\nimport path from "node:path";\n') + `Config.overrideWebpackConfig((c) => ({
  ...c,
  resolve: {
    ...c.resolve,
    alias: {
      ...(c.resolve?.alias as Record<string, string> | undefined),
      remotion: path.resolve(process.cwd(), "node_modules/remotion"),
      react: path.resolve(process.cwd(), "node_modules/react"),
      "react-dom": path.resolve(process.cwd(), "node_modules/react-dom"),
    },
  },
}));
`;
export const tsconfig = JSON.stringify({ compilerOptions: { target: "ES2018", module: "Preserve", moduleResolution: "Bundler", jsx: "react-jsx", strict: true, noEmit: true, lib: ["es2015", "dom"], esModuleInterop: true, skipLibCheck: true, resolveJsonModule: true }, include: ["src", "episodes"] }, null, 2) + "\n";
export const indexTs = `import { registerRoot } from "remotion";
import { RemotionRoot } from "./Root";

registerRoot(RemotionRoot);
`;
export const brandTs = `import { themeFromBrand } from "@praeko/studio-core";
import brand from "../brand.json";

export { brand };
export const theme = themeFromBrand(brand as Parameters<typeof themeFromBrand>[0]);
`;
/** Markers `praeko-studio:imports` / `praeko-studio:compositions` are how `praeko studio new` registers episodes. */
export const MARKER_IMPORTS = "praeko-studio:imports", MARKER_COMPOSITIONS = "praeko-studio:compositions";
export const MARKER_IMPORTS_END = "praeko-studio:/imports", MARKER_COMPOSITIONS_END = "praeko-studio:/compositions";
export const rootTsx = `// The "praeko-studio:" comments are used by \`praeko studio new\` to register episodes: do not delete them.
// ${MARKER_IMPORTS}
// ${MARKER_IMPORTS_END}

export const RemotionRoot: React.FC = () => (
  <>
    {/* ${MARKER_COMPOSITIONS} */}
    {/* ${MARKER_COMPOSITIONS_END} */}
  </>
);
`;
