export const episodeYaml = ({ id, cover, title }: { id: string; cover: string; title: string }): string => `# ${title}
# Edit here; \`praeko studio compile <slug>\` checks the anchors and writes episode.spec.json (render and cover already compile on their own).
id: ${id}
duration: 13         # s. After \`praeko studio voice\`, leave ~3 s after the end of the voice
caption: 80
voice: audio/${id}.mp3
background: ["${title}"]
outro: { start: 9.5, cta: FOLLOW FOR MORE }   # the voice must end before this
cover: { id: ${cover}, component: ${cover} }          # TSX piece in scenes.tsx
scenes:
  - start: 0
    title: ${title.toUpperCase().slice(0, 28)}
    label: ${title.toUpperCase().slice(0, 18)}
    items:
      # \`when\` ties the item to a phrase of the voice (it appears when the phrase is spoken). Text with a comma goes in quotes.
      - { type: big, at: 0.2, color: accent, size: 92, text: "${title.replace(/"/g, "'")}" }
`;

export const scenesTsx = ({ cover, lines }: { cover: string; lines: string[] }): string => `import { Frame } from "@praeko/studio-kit";
import { theme } from "../../src/brand";

/** TSX pieces of the episode (the cover and whatever the YAML cannot express). Reference them in episode.yaml with \`component\`. */
export const ${cover}: React.FC = () => (
  <Frame glow="rgba(244,185,66,.16)" title={${JSON.stringify(lines)}} color={theme.accent} size={104}>
    <div />
  </Frame>
);
`;

export const episodeTsx = ({ id, slug }: { id: string; slug: string }): string => `import { EpisodeDecl } from "@praeko/studio-kit";
import type { EpisodeSpec } from "@praeko/studio-kit";
import { theme } from "../../src/brand";
import * as components from "./scenes";
import spec from "./episode.spec.json";
import { WORDS } from "./words";

// episode.spec.json is generated from episode.yaml (\`praeko studio compile ${slug}\`). Edit the YAML, not this file.
export const ${id}Composition = () => <EpisodeDecl spec={spec as EpisodeSpec} words={WORDS} theme={theme} components={components} />;
`;

export const wordsTs = (words: unknown[] = []): string => `import type { Word } from "@praeko/studio-core";\n\nexport const WORDS: Word[] = ${JSON.stringify(words)};\n`;

export const longScript = `## 1 · THE HOOK
[curious] Write the hook of the video here.

## 2 · THE PROBLEM
Each block becomes one audio (cached): editing a block only regenerates that block.

## 3 · THE LESSON
[confident] Close with the main idea.
`;

export const longYaml = ({ id, title }: { id: string; title: string }): string => `# Long (16:9): ${title}
# \`praeko studio voice <slug> --quality draft\` writes blocks.json (start of each script block); \`start: { block: N }\` uses that time.
format: long
id: ${id}
duration: 60           # s, whole video (leave ~3 s after the end of the voice)
voice: audio/${id}.mp3
scenes:
  - title: THE HOOK
    start: 0
    items:
      # code | card (with items: text) | chip | freetext. Absolute position in px (1920×1080); \`when\` = the phrase of the voice that makes the item enter.
      - { type: freetext, when: { when: "Write the hook", after: 0 }, pos: { left: 200, top: 400, width: 1500 }, size: 80, color: accent, text: "${title.replace(/"/g, "'")}" }
`;

export const longScenesTsx = `// Long-video scenes the YAML cannot express: export React.FC<{ t: number }> (t = seconds since the start of the video) and use \`component: Name\` in episode.yaml.
// Pieces: CodeL, CardL, ChipL, TextL (@praeko/studio-kit); anchors: makeAtGlobal(WORDS) (@praeko/studio-core).
export {};
`;

export const longTsx = ({ id, slug }: { id: string; slug: string }): string => `import { LongDecl } from "@praeko/studio-kit";
import type { LongSpec } from "@praeko/studio-kit";
import { theme } from "../../src/brand";
import * as components from "./scenes";
import spec from "./episode.spec.json";
import { WORDS } from "./words";

// episode.spec.json is generated from episode.yaml (\`praeko studio compile ${slug}\`). Edit the YAML, not this file.
export const ${id}Composition = () => <LongDecl spec={spec as LongSpec} words={WORDS} theme={theme} components={components as any} />;
`;
